{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "느린 쿼리의 병목에 맞는 개선 방법을 선택하는 능력을 검증한다. 신고 목록 조회 쿼리의 개선 방법을 정한 근거를 중심으로 원인 분석과 수치로 확인한 효과의 연결을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 운영 화면의 신고 목록 조회 쿼리에 3.2초가 걸렸던 상황이다.",
          "task": "조회 지연의 원인에 맞는 쿼리 개선 방법을 선택해야 했다.",
          "action": "실행 계획에서 확인한 병목을 바탕으로 실제 적용한 개선 방법이 적절하다고 판단한 이유를 설명한다.",
          "result": "조회 시간이 3.2초에서 0.4초로 줄어든 사실을 선택한 개선 방법의 효과와 연결한다. 수치의 비교 조건은 실제 확인한 범위에서 설명한다."
        },
        "expectedEvidence": [
          "신고 목록 조회 쿼리의 개선 방법을 선택한 구체적인 근거",
          "실행 계획에서 확인한 전체 조인 등 병목과 선택한 개선 방법 사이의 인과관계",
          "개선 전후 응답 시간 수치가 해당 선택의 효과를 뒷받침하는 설명"
        ]
      },
      "question": "포켓마켓에서 3.2초가 걸리던 신고 목록 조회 쿼리를 개선할 때, 적용할 개선 방법을 정한 근거는 무엇이었나요?",
      "answerTip": "본인이 겪은 한 장면을 중심으로 구체적으로 답해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "쿼리 개선 방법을 선택한 근거가 구체적이며, 실제 확인한 병목에 기초한다.",
            "실행 계획에서 발견한 문제와 선택한 방법이 조회 비용을 줄이는 이유를 일관되게 연결한다.",
            "3.2초에서 0.4초로 줄어든 전후 수치를 선택한 방법의 효과와 연결해 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "개선 방법을 선택한 근거는 제시하지만 병목과의 연결이 부분적으로만 드러난다.",
            "실행 계획의 문제나 개선 전후 수치를 언급하지만, 그것이 해당 방법의 적절성을 뒷받침하는 설명은 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "개선 방법을 선택한 근거가 없거나 적용한 기술 이름만 나열한다.",
            "병목에 관한 관찰이나 전후 측정 수치 없이 빨라졌다는 주장만 제시한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "배포 후 오류를 로그로 추적하여 원인을 좁히는 능력을 검증한다. 알림 중복 발송의 원인을 스케줄러 중복 실행으로 판단한 근거를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 다음 날 같은 알림이 두 번 발송된다는 문의가 들어온 상황이다.",
          "task": "알림 중복 발송의 원인을 로그에 근거해 좁혀야 했다.",
          "action": "시간순으로 살펴본 로그에서 실제 확인한 사실을 들어 스케줄러가 두 서버에서 동시에 실행된 것이 원인이라고 판단한 이유를 설명한다.",
          "result": "로그에서 확인한 실행 양상이 알림 중복 발송을 설명하며, 처음 의심했던 클라이언트 문제보다 서버의 스케줄러 중복 실행을 원인으로 판단할 수 있었음이 드러난다."
        },
        "expectedEvidence": [
          "알림 중복 발송의 원인을 스케줄러 중복 실행으로 좁힌 구체적인 판단 근거",
          "시간순 로그에서 확인한 두 서버의 동시 실행과 알림 중복 발송 사이의 연결",
          "처음의 클라이언트 문제 추정 대신 서버 측 원인을 지목할 수 있었던 사실"
        ]
      },
      "question": "포켓마켓에서 배포 후 알림 중복 발송을 추적할 때, 오류 원인이 스케줄러 중복 실행이라고 판단한 근거는 무엇이었나요?",
      "answerTip": "당시 상황을 모르는 사람에게 말하듯 답해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "스케줄러 중복 실행을 오류 원인으로 좁힌 판단 근거가 실제 로그 관찰에 기반해 구체적으로 드러난다.",
            "두 서버의 동시 실행이 같은 알림의 중복 발송으로 이어졌다고 판단한 연결을 명확히 설명한다.",
            "클라이언트 문제라는 초기 추정보다 서버 측 원인에 무게를 둔 이유를 관찰한 사실로 뒷받침한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "스케줄러 중복 실행을 원인으로 판단한 근거는 있으나 로그에서 확인한 사실이 구체적이지 않다.",
            "두 서버의 실행과 알림 중복 발송의 연관성은 설명하지만, 초기 추정을 바꾼 이유나 인과관계의 설명이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "원인을 좁힌 판단 근거 없이 스케줄러 문제였다는 결론만 제시한다.",
            "로그에서 확인한 사실과 중복 발송의 관계를 설명하지 못하거나, 원인 판단 대신 수정 조치만 설명한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "사용자 요청의 목적과 범위를 구현 가능한 요구사항으로 구체화하는 역량을 검증한다. 요구사항 정의서에서 이번 구현에 포함할 범위를 정한 기준 하나에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "세탁소 5곳의 인터뷰를 바탕으로 동네 세탁소 예약 서비스의 요구사항 정의서를 작성한 상황",
          "task": "인터뷰에서 나온 요청을 서비스 목적에 맞는 구현 범위로 구체화해야 했던 과제",
          "action": "요청의 목적과 필요성을 비교해 이번 구현에 포함할 범위를 정한 기준을 구체적인 요구사항 사례로 설명",
          "result": "그 기준에 따라 포함하거나 제외한 범위가 명확해진 내용과 개발 담당 팀원과의 범위 조정에 활용된 정도"
        },
        "expectedEvidence": [
          "이번 구현에 포함할 요구사항의 범위를 정한 구체적인 기준",
          "그 기준을 뒷받침한 사용자 요청의 목적이나 우선순위에 관한 사실",
          "기준을 적용한 요구사항 사례에서 드러나는 포함 범위와 제외 범위의 경계"
        ]
      },
      "question": "동네 세탁소 예약 서비스의 요구사항 정의서를 작성할 때, 이번 구현에 포함할 범위를 정한 기준은 무엇이었나요?",
      "answerTip": "기억나는 사례 하나를 중심으로 구체적으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "이번 구현에 포함할 범위를 정한 기준을 구체적으로 설명한다.",
            "사용자 요청의 목적이나 우선순위에 관한 사실을 들어 해당 기준이 필요했던 이유를 설명한다.",
            "실제 요구사항에 기준을 적용한 사례에서 포함할 범위와 제외할 범위의 경계가 명확하게 드러난다."
          ]
        },
        "acceptable": {
          "criteria": [
            "구현 범위를 정한 기준은 제시하지만 포괄적이거나 적용 조건이 불명확하다.",
            "사용자 요청과 기준의 연결은 확인되지만 목적이나 우선순위에 대한 설명이 부족하다.",
            "범위 결정 사례는 있으나 포함하거나 제외한 경계가 일부 모호하다."
          ]
        },
        "poor": {
          "criteria": [
            "구현 범위를 정한 기준을 제시하지 못하거나 작성한 문서의 내용만 나열한다.",
            "범위 결정이 사용자 요청의 목적이나 필요성과 어떻게 연결되는지 설명하지 못한다.",
            "실제 요구사항에 기준을 적용한 사례가 없어 포함 범위와 제외 범위를 확인하기 어렵다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "기능 흐름과 예외 상황을 구현 가능한 화면설계로 구체화하는 역량을 검증한다. 화면설계서에서 예외 상황을 화면 흐름에 반영하는 방식을 정한 기준 하나에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스에서 기능 흐름과 예외 상황을 포함한 화면설계서 28장을 작성한 상황",
          "task": "예외 상황에서도 화면의 동작을 개발자와 디자이너가 해석할 수 있게 구체화해야 했던 과제",
          "action": "실제로 다룬 예외 상황을 바탕으로 화면 흐름에 반영할 방식을 정한 기준과 그 이유를 설명",
          "result": "선택한 방식에 따라 예외 발생 시 화면 상태나 이동, 사용자 안내의 의미가 명확해진 내용"
        },
        "expectedEvidence": [
          "예외 상황을 화면 흐름에 구체화하는 방식을 정한 기준",
          "그 기준이 필요했던 실제 예외 상황과 화면 동작상의 문제",
          "선택한 표현 방식이 화면 상태나 이동, 안내의 해석을 명확하게 만든 구체적인 사례"
        ]
      },
      "question": "동네 세탁소 예약 서비스의 화면설계서 28장을 작성할 때, 예외 상황을 화면 흐름에 구체화하는 방식을 정한 기준은 무엇이었나요?",
      "answerTip": "직접 했던 일을 중심으로 차분하게 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "예외 상황을 화면 흐름에 구체화하는 방식을 정한 기준을 명확하게 설명한다.",
            "실제 예외 상황에서 어떤 화면 동작의 불명확함을 해소해야 했는지 구체적으로 설명한다.",
            "선택한 방식이 화면 상태나 이동, 안내를 어떻게 명확하게 표현했는지 사례로 보여 주어 구현에 필요한 해석이 가능하다."
          ]
        },
        "acceptable": {
          "criteria": [
            "예외 상황을 화면에 반영한 기준은 제시하지만 구체적인 판단 이유가 부족하다.",
            "실제 예외 상황을 언급하지만 화면 동작상의 문제와 기준의 연결이 일부 모호하다.",
            "선택한 표현 방식의 사례는 있으나 화면이 어떻게 동작하는지 일부 해석이 필요하다."
          ]
        },
        "poor": {
          "criteria": [
            "예외 상황을 화면 흐름에 반영하는 방식을 정한 기준을 설명하지 못한다.",
            "화면 수나 사용 도구만 설명해 실제 예외 상황과 판단의 연결을 확인할 수 없다.",
            "제시한 사례에서 예외 발생 시 화면 동작이 드러나지 않아 구현 가능한 구체성을 확인하기 어렵다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "처방의 정확성이 의심되는 상황에서 투약을 그대로 진행하지 않는 판단을 검증한다. 평소 용량의 두 배로 입력된 진통제 처방에 대해 투약을 멈추기로 한 근거 하나를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "정형외과 병동에서 수술 후 환자의 진통제 처방 용량이 평소 용량의 두 배로 입력된 경험이다.",
          "task": "해당 처방에 따라 투약을 진행해도 되는지 판단해야 하는 상황이다.",
          "action": "처방 용량의 차이를 이상 신호로 보고, 정확성이 확인되지 않은 상태에서는 투약을 진행할 수 없다고 판단한 근거가 드러난다.",
          "result": "투약 전 중단 판단이 확인되지 않은 처방의 실행을 막았다는 의미가 드러난다."
        },
        "expectedEvidence": [
          "진통제 투약을 멈추기로 판단한 구체적인 근거",
          "평소 용량과 처방 용량의 차이를 처방 확인이 필요한 신호로 해석한 이유",
          "처방의 정확성이 확인되지 않은 상태에서 투약을 진행할 경우의 환자 안전 위험에 대한 인식"
        ]
      },
      "question": "수술 후 환자의 진통제 처방 용량이 평소의 두 배로 들어온 사례에서, 투약을 멈추기로 판단한 근거를 말씀해 주세요.",
      "answerTip": "당시 상황을 짧게 짚고 본인의 생각을 설명해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "투약을 멈춘 근거를 해당 환자의 진통제 처방 용량에 대한 의심과 명확하게 연결한다.",
            "평소 용량과의 차이를 단순히 낯선 처방이 아니라 정확성 확인이 필요한 신호로 해석한 이유를 구체적으로 설명한다.",
            "확인되지 않은 용량으로 투약할 위험과 중단 판단의 관계를 설명한다."
          ]
        },
        "acceptable": {
